with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('7532bcf5-7bf5-4d5b-964d-8e4025f1983e'::uuid,ARRAY['Adjective い informal nonpast 限りだ Where adjectiveい＝emotive adjective']::text[],ARRAY['Use this construction to express A phrase that indicates the extreme degree of the speaker’s/writer’s emotion — happiness, sorrow, envy, shame or loneliness, among others. A phrase that indicates the extreme degree of the speaker’s/writer’s emotion — happiness, sorrow, envy, shame or loneliness, among others']::text[],ARRAY['【Related Expression: この上ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"いろいろなところに行っておられるんですね。うらやましい限りです。","japanese_furigana":"いろいろなところに行っておられるんですね。うらやましい限りです。","english":"You are traveling to all sorts of places. I''m extremely envious of you."},{"japanese":"電子メールでご連絡いただければ、嬉しい限りです。","japanese_furigana":"電子メールでご連絡いただければ、嬉しい限りです。","english":"I would be extremely happy if you would kindly contact me by e-mail."}]'::jsonb),
    ('421bf26c-d4ed-4167-952e-2323da3826aa'::uuid,ARRAY['Noun 面']::text[],ARRAY['Use this construction to express A suffix which forms a compound that means a side of X, or an aspect of X.. A suffix which forms a compound that means a side of X, or an aspect of X.']::text[],ARRAY['【Related Expression: 点(で)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼か学業面では優秀だが、精神面に少し弱さがあるようだ。","japanese_furigana":"彼か学業面では優秀だが、精神面に少し弱さがあるようだ。","english":"He is excellent in terms of his academic performance (literally: on the side of his academic performance) but he seems to have some psychological weakness (literally: have some weakness on the side of his psychology)."},{"japanese":"この食堂は衛生面によく気を配っている。","japanese_furigana":"この食堂は衛生面によく気を配っている。","english":"This restaurant pays close attention to hygiene (literally: the hygienic aspect)."}]'::jsonb),
    ('8479ff3f-d020-41a4-b3ee-15ebc7ec13c4'::uuid,ARRAY['(i) Vinformal past ( っ ) きり']::text[],ARRAY['Use this construction to express A conjunction indicating that since something occurred, nothing has happened and the resultant situation remains unchanged; a particle indicating a strict limitation in terms of number/quantity.. A conjunction indicating that since something occurred, nothing has happened and the resultant situation remains unchanged; a particle indicating a strict limitation in terms of number/quantity.']::text[],ARRAY['【Related Expression: だけ; まま】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山下氏は1964年に日本を出た（っ）きり日本には一度も帰っていない。","japanese_furigana":"山下氏は1964年に日本を出た（っ）きり日本には一度も帰っていない。","english":"Mr. Yamashita hasn''t returned to Japan even once since he left in 1964."},{"japanese":"ソウルにいるのも今夜きりです。","japanese_furigana":"ソウルにいるのも今夜きりです。","english":"This is my last night (literally: the only night left) in Seoul."}]'::jsonb),
    ('21f0d760-f376-4f5e-8ca9-3206bd306e6a'::uuid,ARRAY['(i) {V/Adjective い} informal 代わりに']::text[],ARRAY['Use this construction to express An action/state that is expressed in the subordinate clause is balanced by another action/state expressed in the main clause, or something/someone that is replaced by something/someone else.. An action/state that is expressed in the subordinate clause is balanced by another action/state expressed in the main clause, or something/someone that is replaced by something/someone else.']::text[],ARRAY['【Related Expression: が; から; けれど(も); ないで; ので; しかし; ずに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"昼間遊ぶ代わりに夜勉強するつもりだ。","japanese_furigana":"昼間遊ぶ代わりに夜勉強するつもりだ。","english":"I am going to enjoy myself in the daytime, so /but (to make up for it) I will study at night."},{"japanese":"山田さんにはちょっと余分に働いてもらった代わりに特別手当てを出した。","japanese_furigana":"山田さんにはちょっと余分に働いてもらった代わりに特別手当てを出した。","english":"Mr. Yamada worked for us a bit extra, so / but (to make up-for it) we paid him special compensation."}]'::jsonb),
    ('294f4aef-d6b0-43e7-bc01-8bd086c6aba3'::uuid,ARRAY['(i) Group 1 verbs Vconditional Affirmative']::text[],ARRAY['Use this construction to express Verb forms which indicate commands or requests.. Verb forms which indicate commands or requests.']::text[],ARRAY['【Related Expression: こと; なさい; てはいけない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もうよせよ。","japanese_furigana":"もうよせよ。","english":"Stop it now."},{"japanese":"ここには十二月三十一日までに払えと書いてある。","japanese_furigana":"ここには十二月三十一日までに払えと書いてある。","english":"It says here to pay before December 31."}]'::jsonb),
    ('4e5fbc20-13dc-4896-a9e2-fd607702ff9d'::uuid,ARRAY['Canonical pattern: Rhetorical Question']::text[],ARRAY['Use this construction to express A question which functions as a forceful statement with no expected response.. A question which functions as a forceful statement with no expected response.']::text[],ARRAY['The core sense is A question which functions as a forceful statement with no expected response.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"そんな恥ずかしいことが出来ますか。","japanese_furigana":"そんな恥ずかしいことが出来ますか。","english":"I could never do such an embarrassing thing! (literally: Could I do such an embarrassing thing?)"},{"japanese":"誰があんな人にお金なんか貸すもんですか。","japanese_furigana":"誰があんな人にお金なんか貸すもんですか。","english":"Who would lend money to such a person!"}]'::jsonb),
    ('c4fd45ae-14fa-4471-a8a3-dd41e337dcdc'::uuid,ARRAY['Canonical pattern: Vmasu']::text[],ARRAY['Use this construction to express A continuative form of a verb which means "V and...".. A continuative form of a verb which means "V and...".']::text[],ARRAY['【Related Expression: Verb て Form】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ジョンは日本で生まれ、十歳まで日本の学校で勉強した。","japanese_furigana":"ジョンは日本で生まれ、十歳まで日本の学校で勉強した。","english":"John was born in Japan and studied at a Japanese school until he was ten."},{"japanese":"父は銀行に勤め、母はうちの近くでブティックを開いている。","japanese_furigana":"父は銀行に勤め、母はうちの近くでブティックを開いている。","english":"My father works for a bank and my mother has a boutique near my house."}]'::jsonb),
    ('4498cd16-27ac-4c9f-9680-01b84b77a179'::uuid,ARRAY['Canonical pattern: Vmasu as a Noun']::text[],ARRAY['Use this construction to express Vます used as a regular noun.. Vます used as a regular noun.']::text[],ARRAY['The core sense is Vます used as a regular noun.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼はまだ若いから、考えが浅い。","japanese_furigana":"彼はまだ若いから、考えが浅い。","english":"Because he is still young, his thoughts are shallow."},{"japanese":"日本語は、話すのは比較的易しいが、読み書きは難しい。","japanese_furigana":"日本語は、話すのは比較的易しいが、読み書きは難しい。","english":"It is relatively easy to speak Japanese, but reading and writing are hard."}]'::jsonb),
    ('619f6fe3-b485-4288-9188-04eab2629124'::uuid,ARRAY['あえて Verb']::text[],ARRAY['Use this construction to express An adverb that expresses the speaker''s/writer''s desire or will to dare to do something in spite of difficulty, danger or opposition.. An adverb that expresses the speaker''s/writer''s desire or will to dare to do something in spite of difficulty, danger or opposition.']::text[],ARRAY['【Related Expression: 思いきって; しいて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"部長はあえて社長に反対意見を述べた。","japanese_furigana":"部長はあえて社長に反対意見を述べた。","english":"The department head boldly expressed his opposing view directly to the company president."},{"japanese":"私はあえて大がかりな研究計画を立てたいと思う。","japanese_furigana":"私はあえて大がかりな研究計画を立てたいと思う。","english":"I would like to take on a large-scale research proposal."}]'::jsonb),
    ('94ef2930-6c71-431a-8323-c9d629e4f0a1'::uuid,ARRAY['Canonical pattern: あくまでも']::text[],ARRAY['Use this construction to express An adverb that represents the idea of "to the utmost degree".. An adverb that represents the idea of "to the utmost degree".']::text[],ARRAY['【Related Expression: どこまでも; 最後まで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"江本氏はあくまでも自説を変えなかった。","japanese_furigana":"江本氏はあくまでも自説を変えなかった。","english":"Mr. Emoto persistently maintained (literally: didn''t change) his opinion."},{"japanese":"これはあくまでも小説であって実話ではない。","japanese_furigana":"これはあくまでも小説であって実話ではない。","english":"literally: This is strictly fiction and not a true story."}]'::jsonb),
    ('8149399d-7b7c-41b4-93ad-b8171cf7498a'::uuid,ARRAY['(i) Vinformal past あげく (に)']::text[],ARRAY['Use this construction to express An adverb/conjunction indicating that one spends an extended period of time before reaching a result.. An adverb/conjunction indicating that one spends an extended period of time before reaching a result.']::text[],ARRAY['Adverb/Conjunction. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"さんざん考えたあげく（に）大学院へ進学することにした。","japanese_furigana":"さんざん考えたあげく（に）大学院へ進学することにした。","english":"After thinking for a long time, I decided to go on to graduate school."},{"japanese":"彼女の離婚は数年悩んだあげくの決断だった。","japanese_furigana":"彼女の離婚は数年悩んだあげくの決断だった。","english":"Her divorce was a decision she made after agonizing for several years."}]'::jsonb),
    ('6799c01a-b8ec-48d1-9dc4-111b50e2d516'::uuid,ARRAY['(i) あたかも Noun の{ように/ようなNoun}']::text[],ARRAY['Use this construction to express An adverb used to present a counter-factual statement emphatically. An adverb used to present a counter-factual statement emphatically']::text[],ARRAY['【Related Expression: まるで; かのように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はあたかも責任者のように振る舞っている。","japanese_furigana":"彼はあたかも責任者のように振る舞っている。","english":"He behaves as if he were the person in charge."},{"japanese":"リニアモーターカーはあたかも氷の上をすべる（かの）ように走る。","japanese_furigana":"リニアモーターカーはあたかも氷の上をすべる（かの）ように走る。","english":"The linear motor car runs as if it were gliding on ice."}]'::jsonb),
    ('52a79660-4702-42ee-af57-bd3dc3ec6a58'::uuid,ARRAY['Vinformal past あとで']::text[],ARRAY['Use this construction to express Some state or action takes place at a time (not always immediately) after another state or action has taken place.. Some state or action takes place at a time (not always immediately) after another state or action has taken place.']::text[],ARRAY['【Related Expression: たら; てから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"メイソンさんは日本へ行ったあとで病気になった・なりました。","japanese_furigana":"メイソンさんは日本へ行ったあとで病気になった・なりました。","english":"Mr. Mason became ill after he went to Japan."},{"japanese":"私は授業のあとで図書館に行った・行きました。","japanese_furigana":"私は授業のあとで図書館に行った・行きました。","english":"After the class I went to the library."}]'::jsonb),
    ('72ff0761-d0a4-4706-b889-d8c1d963faed'::uuid,ARRAY['Canonical pattern: あまり（程度が低い）']::text[],ARRAY['Use this construction to express The degree of something is not great.. The degree of something is not great.']::text[],ARRAY['The core sense is The degree of something is not great.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この本はあまりよくない・よくありません。","japanese_furigana":"この本はあまりよくない・よくありません。","english":"This book is not very good."},{"japanese":"鈴木さんはあまり食べない。","japanese_furigana":"鈴木さんはあまり食べない。","english":"Miss Suzuki does not eat much."}]'::jsonb),
    ('a7ff5e79-ccc3-49da-b1de-a016234a00a7'::uuid,ARRAY['Canonical pattern: ある（存在）']::text[],ARRAY['Use this construction to express An inanimate thing exists.. An inanimate thing exists.']::text[],ARRAY['【Related Expression: いる1; もっている】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この町（に）は大学が三つある・あります。","japanese_furigana":"この町（に）は大学が三つある・あります。","english":"In this town are three universities."},{"japanese":"エッフェル塔はパリにある・あります。","japanese_furigana":"エッフェル塔はパリにある・あります。","english":"The Eiffel Tower is in Paris."}]'::jsonb),
    ('e094e510-d51c-4484-afdb-44c1d8ea1d2a'::uuid,ARRAY['(i) Noun 1 (か)、 < あるいは Noun 2']::text[],ARRAY['Use this construction to express A conjunction that marks alternatives. A conjunction that marks alternatives']::text[],ARRAY['【Related Expression: それとも; また; ないし(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ボールペン(か)あるいは万年筆でお書き下さい。","japanese_furigana":"ボールペン(か)あるいは万年筆でお書き下さい。","english":"Please write either with a ballpoint pen or a fountain pen."},{"japanese":"日本のような少子化社会では、大学の数を少なくするか、あるいは外国人の学生を増やすかしなければなるまい。","japanese_furigana":"日本のような少子化社会では、大学の数を少なくするか、あるいは外国人の学生を増やすかしなければなるまい。","english":"In a society like Japan where the number of children is decreasing, we may have to either reduce the number of colleges or increase the number of foreign students."}]'::jsonb),
    ('69d3a477-6526-491c-991e-8720eaf13c5b'::uuid,ARRAY['(i) いかなる Noun (particle)～か']::text[],ARRAY['Use this construction to express A noun modifier that means either “what kind of” or “no matter what”.. A noun modifier that means either “what kind of” or “no matter what”.']::text[],ARRAY['【Related Expression: どんな; どのような】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"生物社会学とはいかなる学問分野（なの）か。","japanese_furigana":"生物社会学とはいかなる学問分野（なの）か。","english":"What kind of academic ﬁeld is bio-sociology?"},{"japanese":"彼はいかなる忠告（に）も耳を貸さなかった。","japanese_furigana":"彼はいかなる忠告（に）も耳を貸さなかった。","english":"He didn''t lend an ear to any kind of advice."}]'::jsonb),
    ('4fb5899b-0baf-4a29-9d9f-a03aa99293e7'::uuid,ARRAY['(i) いかに {V/Adjective い}informalか']::text[],ARRAY['Use this construction to express An adverb meaning “how”.. An adverb meaning “how”.']::text[],ARRAY['【Related Expression: どんなに; なんと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"いかに日本語が難しいかは学習者の母語による。","japanese_furigana":"いかに日本語が難しいかは学習者の母語による。","english":"How difficult Japanese is (for someone) depends on the learner''s mother tongue."},{"japanese":"いかに運動しても長生きできるとは限らない。","japanese_furigana":"いかに運動しても長生きできるとは限らない。","english":"No matter how hard one exercises, it doesn''t guarantee a long life."}]'::jsonb),
    ('4c9812ad-0ed4-42c7-811c-16bb686cc569'::uuid,ARRAY['Canonical pattern: いかにも']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker/writer''s emotive conviction.. An adverb that indicates the speaker/writer''s emotive conviction.']::text[],ARRAY['【Related Expression: 本当に; 確かに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"アメリカ人の目から見ると、日本の社会はいかにも閉鎖的だ。","japanese_furigana":"アメリカ人の目から見ると、日本の社会はいかにも閉鎖的だ。","english":"From an American perspective, Japanese society is indeed closed."},{"japanese":"外は雪が降っていて、いかにも寒そうだ。","japanese_furigana":"外は雪が降っていて、いかにも寒そうだ。","english":"It is snowing outside, and it looks really cold."}]'::jsonb),
    ('b21b12ea-17ec-45b8-9b64-1a21a705618e'::uuid,ARRAY['(i) いくら {Vて/Adjectiveいstemくて/Adjectiveなstemで}も']::text[],ARRAY['Use this construction to express A Wh-word that asks about the amount of something.. A Wh-word that asks about the amount of something.']::text[],ARRAY['【Related Expression: どんなに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"東京の3DKのマンションはいくらぐらいですか。","japanese_furigana":"東京の3DKのマンションはいくらぐらいですか。","english":"Approximately how much is a 3DK (3 rooms with a dining room / kitchen) apartment in Tokyo?"},{"japanese":"いくら働いてもお金が貯まらない。","japanese_furigana":"いくら働いてもお金が貯まらない。","english":"No matter how much I work I can''t save money."}]'::jsonb),
    ('3e2778f4-cc8f-436a-8ad8-b157fb6963ed'::uuid,ARRAY['Canonical pattern: いる（存在）']::text[],ARRAY['Use this construction to express An animate thing exists.. An animate thing exists.']::text[],ARRAY['【Related Expression: ある1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この町(に)は日本人が沢山いる・います。","japanese_furigana":"この町(に)は日本人が沢山いる・います。","english":"In this town are many Japanese."},{"japanese":"リーはこの寮にいる・います。","japanese_furigana":"リーはこの寮にいる・います。","english":"Lee is in this dorm."}]'::jsonb),
    ('a8ff68f7-f931-406b-aad1-ad81426cd0cf'::uuid,ARRAY['いわゆる Noun']::text[],ARRAY['Use this construction to express A noun modifier that means “known generally by this term”.. A noun modifier that means “known generally by this term”.']::text[],ARRAY['The core sense is A noun modifier that means “known generally by this term”.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"伊藤さんはいわゆる「エリート」の大学を卒業した。","japanese_furigana":"伊藤さんはいわゆる「エリート」の大学を卒業した。","english":"Ms. Ito graduated from one of the so-called \"elite” universities."},{"japanese":"いわゆるリストラのために失業した人は非常に多い。","japanese_furigana":"いわゆるリストラのために失業した人は非常に多い。","english":"Many people lost their jobs because of what is called restructuring."}]'::jsonb),
    ('8e14cd66-6dbb-4739-a35a-61e3d23d8757'::uuid,ARRAY['(i) Vinformal nonpast うちに (Verb: stative)']::text[],ARRAY['Use this construction to express During a period when a certain situation remains in effect.. During a period when a certain situation remains in effect.']::text[],ARRAY['【Related Expression: 間(に); 前に; 中(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"前田さんはアメリカにいるうちに英語が上手なった・なりました。","japanese_furigana":"前田さんはアメリカにいるうちに英語が上手なった・なりました。","english":"Mr. Maeda''s English improved while he was in America."},{"japanese":"何もしないうちに今年も終わった・終わりました。","japanese_furigana":"何もしないうちに今年も終わった・終わりました。","english":"Before I''ve achieved anything, this year is over."}]'::jsonb),
    ('4e810fbb-18a5-4e8b-b0ab-acd2b3669f8a'::uuid,ARRAY['お Vます になる']::text[],ARRAY['Use this construction to express A prefix that expresses politeness.. A prefix that expresses politeness.']::text[],ARRAY['【Related Expression: ご】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"石田先生は英語でお話しになった・なりました。","japanese_furigana":"石田先生は英語でお話しになった・なりました。","english":"Professor Ishida talked in English."},{"japanese":"私は昨日山崎先生にお会いした・しました。","japanese_furigana":"私は昨日山崎先生にお会いした・しました。","english":"I met Professor Yamazaki yesterday."}]'::jsonb),
    ('d92695c3-fc11-4988-a3c4-ebd6f80e9e98'::uuid,ARRAY['お Vます になる']::text[],ARRAY['Use this construction to express A phrase which expresses the speaker’s respect for someone when describing that person’s action or state. A phrase which expresses the speaker’s respect for someone when describing that person’s action or state']::text[],ARRAY['【Related Expression: お~する; られる1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"田中先生はもうお帰りになった・なりました。","japanese_furigana":"田中先生はもうお帰りになった・なりました。","english":"Professor Tanaka already went home."},{"japanese":"この本をもうお読みになりましたか。","japanese_furigana":"この本をもうお読みになりましたか。","english":"Have you read this book yet?"}]'::jsonb),
    ('27522009-a910-45b4-9070-2c0a4c7ac450'::uuid,ARRAY['Vて おく']::text[],ARRAY['Use this construction to express Do something in advance for future convenience.. Do something in advance for future convenience.']::text[],ARRAY['【Related Expression: ある2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"明日パーティーをするのでビールを買っておいた・おきました。","japanese_furigana":"明日パーティーをするのでビールを買っておいた・おきました。","english":"Since we are having a party tomorrow, I bought some beer for it."},{"japanese":"今日は昼に客が来るので昼ご飯を早目に食べておいた。","japanese_furigana":"今日は昼に客が来るので昼ご飯を早目に食べておいた。","english":"Since I''m having a guest at noon today, I had my lunch earlier."}]'::jsonb),
    ('f781219f-ed49-48f4-9ac0-62f88e5fc07e'::uuid,ARRAY['(i) およそ Nounは Where Adjective(い/な) has a negative meaning']::text[],ARRAY['Use this construction to express An adverb representing the ideas “all; totally; mostly; approximately”.. An adverb representing the ideas “all; totally; mostly; approximately”.']::text[],ARRAY['【Related Expression: 一般に; 全く; まるで; 大体; おおむね】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はおよそ名作と言われている映画はすべて見ているつもりだ。","japanese_furigana":"私はおよそ名作と言われている映画はすべて見ているつもりだ。","english":"I''m convinced that I''ve watched all the movies that are commonly considered masterpieces."},{"japanese":"彼女はこういう根気のいる仕事にはおよそ向いていない。","japanese_furigana":"彼女はこういう根気のいる仕事にはおよそ向いていない。","english":"She is not at all suited for work that requires perseverance like this work does."}]'::jsonb),
    ('411e8cca-7290-40d6-abf3-2f5f55f990b4'::uuid,ARRAY['Vて おり']::text[],ARRAY['Use this construction to express Vます of the auxiliary verb おる.. Vます of the auxiliary verb おる.']::text[],ARRAY['【Related Expression: いて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この入口は従業員専用になっており、一般の人はここからは入れない。","japanese_furigana":"この入口は従業員専用になっており、一般の人はここからは入れない。","english":"This entrance is for employees only and other people (literally: general people) cannot enter from here."},{"japanese":"彼は最近プラモデルに凝っており、暇さえあれば模型の飛行機に組み立てている。","japanese_furigana":"彼は最近プラモデルに凝っており、暇さえあれば模型の飛行機に組み立てている。","english":"He is crazy about plastic models these days and is assembling model planes whenever he has free time."}]'::jsonb),
    ('16dae025-97b0-4ffd-b984-fdd47bd520f0'::uuid,ARRAY['Canonical pattern: かえって']::text[],ARRAY['Use this construction to express Contrary to one''s expectation an opposite result comes about.. Contrary to one''s expectation an opposite result comes about.']::text[],ARRAY['【Related Expression: むしろ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"薬を飲んだら、かえって病気がひどくなった。","japanese_furigana":"薬を飲んだら、かえって病気がひどくなった。","english":"I took medicine, and the illness got worse (contrary to my expectation)."},{"japanese":"Ａ：一時間も泳いで、疲れたでしょう。 Ｂ：いや、かえって元気になったよ。","japanese_furigana":"Ａ：一時間も泳いで、疲れたでしょう。 Ｂ：いや、かえって元気になったよ。","english":"A: You must be tired after swimming as long as one hour. B: No, on the contrary, I feel fit now."}]'::jsonb),
    ('2ffe3ca3-ede7-4f0c-9a00-50fb0874ffbd'::uuid,ARRAY['(i) ~{V/Adjective い} informal かと言うと 、 S']::text[],ARRAY['Use this construction to express A conjunction to indicate the speaker''s assertion that a popular belief is not right.. A conjunction to indicate the speaker''s assertion that a popular belief is not right.']::text[],ARRAY['The core sense is A conjunction to indicate the speaker''s assertion that a popular belief is not right.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本人はみんな寿司が好きかと言うと、そうではない。嫌いな人もいる。","japanese_furigana":"日本人はみんな寿司が好きかと言うと、そうではない。嫌いな人もいる。","english":"You would think that all the Japanese like sushi, but that is not true. Some Japanese don''t like it."},{"japanese":"がんは治らない病気かと言うと、そうではない。早期発見をすれば治ると言われている。","japanese_furigana":"がんは治らない病気かと言うと、そうではない。早期発見をすれば治ると言われている。","english":"You would think that cancer is not curable, but that is not true. If it is detected early it is said to be curable."}]'::jsonb),
    ('8f3a2ce1-1865-4f53-aa72-a4b3c89ba3fa'::uuid,ARRAY['(i) Adjective い informal nonpast かな Where Adjective い=emotive adjective']::text[],ARRAY['Use this construction to express An interjection that expresses deep felt emotion.. An interjection that expresses deep felt emotion.']::text[],ARRAY['【Related Expression: ことに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"悲しいかな、年を取って往年の記憶力がなくなってしまった。","japanese_furigana":"悲しいかな、年を取って往年の記憶力がなくなってしまった。","english":"How sad (it is) that I no longer have as strong a memory as I had in my younger days."},{"japanese":"悲しいかな、自分の能力を過大評価する人間がいる。","japanese_furigana":"悲しいかな、自分の能力を過大評価する人間がいる。","english":"It''s so sad that there are people who overestimate their ability."}]'::jsonb),
    ('590e50e4-2cca-43e9-a3d0-189153767d42'::uuid,ARRAY['Sinformal からと言って']::text[],ARRAY['Use this construction to express A conjunction which introduces the reason for someone''s action or for someone''s having some idea, and conveys disapproval of the action or idea.. A conjunction which introduces the reason for someone''s action or for someone''s having some idea, and conveys disapproval of the action or idea.']::text[],ARRAY['【Related Expression: から; たって; ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"子供だからと言って許すわけにはいかない。","japanese_furigana":"子供だからと言って許すわけにはいかない。","english":"I cannot forgive him just because he is a child."},{"japanese":"何も不平を言わないからと言って現状に満足しているわけではない。","japanese_furigana":"何も不平を言わないからと言って現状に満足しているわけではない。","english":"Even though I don''t complain, it doesn''t mean that I''m satisfied with the present situation."}]'::jsonb),
    ('f8c6230f-b847-4b48-b48d-df2b8deb81ba'::uuid,ARRAY['Vinformal nonpast が早いか']::text[],ARRAY['Use this construction to express A conjunction indicating that as soon as something happens, something else happens.. A conjunction indicating that as soon as something happens, something else happens.']::text[],ARRAY['【Related Expression: や否や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は朝起きるが早いか、シャワーを浴びた。","japanese_furigana":"彼は朝起きるが早いか、シャワーを浴びた。","english":"As soon as he woke up he took a shower."},{"japanese":"彼女は日本に着くが早いか友人に電話をかけた。","japanese_furigana":"彼女は日本に着くが早いか友人に電話をかけた。","english":"The moment she arrived in Japan she called her friend."}]'::jsonb),
    ('6db8fcf7-11ed-4f86-bfd1-242ff7692d88'::uuid,ARRAY['Canonical pattern: く']::text[],ARRAY['Use this construction to express A continuative form of an い-type adjective.. A continuative form of an い-type adjective.']::text[],ARRAY['【Related Expression: くて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"加奈子の性格は明るく、無邪気だった。","japanese_furigana":"加奈子の性格は明るく、無邪気だった。","english":"Kanako''s personality was cheerful and innocent."},{"japanese":"せっかく講演をしに行ったのに、聴衆が少なく、がっかりした。","japanese_furigana":"せっかく講演をしに行ったのに、聴衆が少なく、がっかりした。","english":"I went all the way to give a lecture, but the audience was so small that I felt discouraged."}]'::jsonb),
    ('48196e91-6552-45fd-b2ea-fbd1ca8f602c'::uuid,ARRAY['(i) Noun のくせに']::text[],ARRAY['Use this construction to express A conjunction which expresses the speaker''s contempt, anger, or disagreement about someone''s action, behaviour, or state.. A conjunction which expresses the speaker''s contempt, anger, or disagreement about someone''s action, behaviour, or state.']::text[],ARRAY['【Related Expression: にもかかわらず; のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さんは日本人のくせにあまり漢字を知らない。","japanese_furigana":"山田さんは日本人のくせにあまり漢字を知らない。","english":"Although Mr. Yamada is Japanese, he doesn''t know many kanji."},{"japanese":"山内はよく知っているくせに何も教えてくれない。","japanese_furigana":"山内はよく知っているくせに何も教えてくれない。","english":"In spite of the fact that Yamauchi knows a lot about it, he doesn''t tell me anything."}]'::jsonb),
    ('05fa6fa4-8086-4a3b-9f17-676f7f7611da'::uuid,ARRAY['Sinformal けれども']::text[],ARRAY['Use this construction to express A disjunctive subordinate conjunction that combines two sentences.. A disjunctive subordinate conjunction that combines two sentences.']::text[],ARRAY['【Related Expression: が2 (だが, だけど, でも, しかし)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は言わなかったけれどもトムは知っていた・いました。","japanese_furigana":"私は言わなかったけれどもトムは知っていた・いました。","english":"Although I didn''t tell him, Tom knew (about it)."},{"japanese":"この本は高いけれどもいい本ですよ。","japanese_furigana":"この本は高いけれどもいい本ですよ。","english":"Although it is expensive, this book is a good book."}]'::jsonb),
    ('6bf1333d-ef97-4ee4-a0d0-f7661e57da6b'::uuid,ARRAY['こうした Noun']::text[],ARRAY['Use this construction to express A demonstrative which refers to someone or something mentioned as an example in previous discourse.. A demonstrative which refers to someone or something mentioned as an example in previous discourse.']::text[],ARRAY['【Related Expression: ああした; こういった; こういう; こんな; このような; そうした】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こうした問題はこの国では聞かれないようである。","japanese_furigana":"こうした問題はこの国では聞かれないようである。","english":"We do not seem to hear about problems like this in this country."},{"japanese":"こうした行為がどのような結果を招くかは誰の目にも明らかだ。","japanese_furigana":"こうした行為がどのような結果を招くかは誰の目にも明らかだ。","english":"It is clear to anyone what kind of result such behaviour brings about."}]'::jsonb),
    ('7c7abc72-9464-4852-ae60-44e513c24f40'::uuid,ARRAY['(i) {V/Adjective い} informal こと']::text[],ARRAY['Use this construction to express A thing which is intangible.. A thing which is intangible.']::text[],ARRAY['【Related Expression: もの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"いいことを教えてあげよう・あげましょう。","japanese_furigana":"いいことを教えてあげよう・あげましょう。","english":"I have a good suggestion for you."},{"japanese":"論文に書いたことを話して下さい。","japanese_furigana":"論文に書いたことを話して下さい。","english":"Please tell me what you wrote in your thesis."}]'::jsonb),
    ('2289ab5f-9eec-42bf-8c3c-dc53831bd53e'::uuid,ARRAY['(i) Wh-word+particle～ Adjectiveいinformal ことか 。']::text[],ARRAY['Use this construction to express A sentence final, exclamatory phrase used in written language.. A sentence final, exclamatory phrase used in written language.']::text[],ARRAY['【Related Expression: ねえ; なあ; なんて/と~の/んだ(ろう)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"カルフォルニアは何と太陽が明るいことか。","japanese_furigana":"カルフォルニアは何と太陽が明るいことか。","english":"How bright the sun is in California!"},{"japanese":"私は今までに何度オーストラリアを訪ねたことか。","japanese_furigana":"私は今までに何度オーストラリアを訪ねたことか。","english":"How many times have I visited Australia before now!"}]'::jsonb),
    ('90ee203d-9554-443d-ab79-9170d8248095'::uuid,ARRAY['Canonical pattern: ごとに']::text[],ARRAY['Use this construction to express Something takes place regularly in succession after a certain temporal or spatial interval.. Something takes place regularly in succession after a certain temporal or spatial interval.']::text[],ARRAY['【Related Expression: まい; おきに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は三時間ごとに薬を飲んだ・飲みました。","japanese_furigana":"私は三時間ごとに薬を飲んだ・飲みました。","english":"I took medicine every three hours."},{"japanese":"正月は家ごとに門松を立てる・立てます。","japanese_furigana":"正月は家ごとに門松を立てる・立てます。","english":"They put up pine tree decorations at every house on New Year''s Day."}]'::jsonb),
    ('235d3f11-57e6-4d0c-a6f9-76c96c7cde0d'::uuid,ARRAY['(i) {V1/Adjective い1} informal ことは {V2/Adjective い2} Where {V1/Adjective い1}={V1/Adjective い2}']::text[],ARRAY['Use this construction to express Speaking of proposition X, X is certainly true.. Speaking of proposition X, X is certainly true.']::text[],ARRAY['The core sense is Speaking of proposition X, X is certainly true.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私はテニスをすることはする・しますが上手じゃない・上手じゃありません。","japanese_furigana":"私はテニスをすることはする・しますが上手じゃない・上手じゃありません。","english":"I do play tennis, but I am not good at it."},{"japanese":"ジョーンズさんは日本語を話すことは話しますが、簡単なことしか言えません。","japanese_furigana":"ジョーンズさんは日本語を話すことは話しますが、簡単なことしか言えません。","english":"Mr. Jones does speak Japanese, but he can say only simply things."}]'::jsonb),
    ('75eba768-9d98-4b53-bfd3-0ba364a8989f'::uuid,ARRAY['(i) この Noun']::text[],ARRAY['Use this construction to express A demonstrative adjective which indicates a time or time period around the moment of speech.. A demonstrative adjective which indicates a time or time period around the moment of speech.']::text[],ARRAY['The core sense is A demonstrative adjective which indicates a time or time period around the moment of speech.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"秋山さんはこの春結婚します。","japanese_furigana":"秋山さんはこの春結婚します。","english":"Miss Akiyama will marry (this spring / this coming spring)."},{"japanese":"山下君はこの一週間授業を休んでいます。","japanese_furigana":"山下君はこの一週間授業を休んでいます。","english":"Yamashita has been absent from class for the past (one) week."}]'::jsonb),
    ('ab78ed83-3df3-4501-9257-4ca61d7eb72a'::uuid,ARRAY['(i) Noun さえ']::text[],ARRAY['Use this construction to express An emphatic particle which expresses the idea of "even" in non-conditional clauses (or sentences) or the idea of "only" in conditional clauses.. An emphatic particle which expresses the idea of "even" in non-conditional clauses (or sentences) or the idea of "only" in conditional clauses.']::text[],ARRAY['【Related Expression: まで; も; すら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は現代日本語は勿論古典さえ読める。","japanese_furigana":"彼女は現代日本語は勿論古典さえ読める。","english":"She can read even classical Japanese, not to mention modern Japanese."},{"japanese":"この研究所にはアメリカからさえ研究者が来る。","japanese_furigana":"この研究所にはアメリカからさえ研究者が来る。","english":"Researchers even from America visit this lab."}]'::jsonb),
    ('a7c67570-797c-41f4-8ca4-e695d4f9c3b7'::uuid,ARRAY['(i) さすが にSentence']::text[],ARRAY['Use this construction to express An adverb that expresses the speaker''s/writer''s strong feeling that something has turned out as s/he expected.. An adverb that expresses the speaker''s/writer''s strong feeling that something has turned out as s/he expected.']::text[],ARRAY['【Related Expression: やはり】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ネルソンさんは日本に三年留学していたので、さすがに日本語が上手です。","japanese_furigana":"ネルソンさんは日本に三年留学していたので、さすがに日本語が上手です。","english":"Because Mr. Nelson has studied in Japan for three years, naturally he speaks Japanese well."},{"japanese":"さすが（は）広島のかきだ。実に美味しい。","japanese_furigana":"さすが（は）広島のかきだ。実に美味しい。","english":"After all, they are Hiroshima oysters. They are really good."}]'::jsonb),
    ('947ebfe5-f23b-4a50-8155-e1ede800dbab'::uuid,ARRAY['(i) Group 1 verbs Vnegative せる']::text[],ARRAY['Use this construction to express Cause someone/something to do something or cause something to change its state.. Cause someone/something to do something or cause something to change its state.']::text[],ARRAY['The core sense is Cause someone/something to do something or cause something to change its state.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"鈴木さんは娘を・に大学へ行かせた・行かせました。","japanese_furigana":"鈴木さんは娘を・に大学へ行かせた・行かせました。","english":"Mr. Suzuki made/let his daughter go to college."},{"japanese":"父は妹にピアノを習わせた・習わせました。","japanese_furigana":"父は妹にピアノを習わせた・習わせました。","english":"My father made (or let) my younger sister learn to play the piano."}]'::jsonb),
    ('a7aafdff-dbbd-403e-8a06-ebdde61fb059'::uuid,ARRAY['(i) さぞ ( かし ) {V/Adjectiveい}informal{だろう/に違いない}/etc.']::text[],ARRAY['Use this construction to express An adverb that is used when the speaker thinks that someone or something is in an extreme state.. An adverb that is used when the speaker thinks that someone or something is in an extreme state.']::text[],ARRAY['【Related Expression: きっと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"被災地の人々はさぞかし困っているだろうと思う。","japanese_furigana":"被災地の人々はさぞかし困っているだろうと思う。","english":"I imagine the people in the disaster-stricken areas are having a really hard time."},{"japanese":"青森への単身赴任はさぞ(かし)大変でしょう。","japanese_furigana":"青森への単身赴任はさぞ(かし)大変でしょう。","english":"Moving to Aomori (for a new assignment) without your family must be very tough."}]'::jsonb),
    ('66c928df-8fcc-4bee-bbb8-d68417f09d60'::uuid,ARRAY['Canonical pattern: さて']::text[],ARRAY['Use this construction to express An interjection indicating that the speaker/writer is going to talk about something different.. An interjection indicating that the speaker/writer is going to talk about something different.']::text[],ARRAY['【Related Expression: ところで; さあ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"さて、私はそろそろ失礼します。","japanese_furigana":"さて、私はそろそろ失礼します。","english":"Well, I should be going now."},{"japanese":"さて、話は変わりますが、日本では今ちょっとした韓国ブームです。","japanese_furigana":"さて、話は変わりますが、日本では今ちょっとした韓国ブームです。","english":"Now, on another matter, Japan is undergoing quite a Korea boom at this time."}]'::jsonb),
    ('dad1ab33-c204-496a-8259-91fb21e01d3e'::uuid,ARRAY['(i) さも {Adjective(い/な)stem/Vます}そう{に/な}']::text[],ARRAY['Use this construction to express An adverb meaning “truly,” used when describing the way someone’s action or behaviour appears.. An adverb meaning “truly,” used when describing the way someone’s action or behaviour appears.']::text[],ARRAY['【Related Expression: いかにも; まるで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"浩二は冷めたコーヒーをさもまずそうに飲んだ。","japanese_furigana":"浩二は冷めたコーヒーをさもまずそうに飲んだ。","english":"Koji drank the cold coffee with a look that showed how bad it tasted."},{"japanese":"古田はさも自分一人が苦労したように言っているが、実は彼は文句を言うばかりで何もしなかったのだ。","japanese_furigana":"古田はさも自分一人が苦労したように言っているが、実は彼は文句を言うばかりで何もしなかったのだ。","english":"Furuta talks as if he suffered alone, but the truth of the matter is that he just complained and didn''t do any work."}]'::jsonb),
    ('5c795613-abcc-48e0-bd2d-5f6cf40718a2'::uuid,ARRAY['Canonical pattern: しい']::text[],ARRAY['Use this construction to express An infix attached to the stem of an adjective い to indicate something that one cannot objectively measure on any scale (e.g. human emotion).. An infix attached to the stem of an adjective い to indicate something that one cannot objectively measure on any scale (e.g. human emotion).']::text[],ARRAY['The core sense is An infix attached to the stem of an adjective い to indicate something that one cannot objectively measure on any scale (e.g. human emotion).; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"悲しい 楽しい らしい 美味しい 苦しい 頼もしい","japanese_furigana":"悲しい 楽しい らしい 美味しい 苦しい 頼もしい","english":"Sad enjoyable seem delicious painful dependable"},{"japanese":"悔しい 厳しい 羨ましい 寂しい 惜しい 妬ましい","japanese_furigana":"悔しい 厳しい 羨ましい 寂しい 惜しい 妬ましい","english":"Regrettable strict envious lonely regrettable enviable"}]'::jsonb),
    ('eaf083b9-dc39-4c48-900d-e8e3aacc143e'::uuid,ARRAY['(i) {V/Adjective/Noun+Copula}て しかも']::text[],ARRAY['Use this construction to express A conjunction which is used to provide additional important information.. A conjunction which is used to provide additional important information.']::text[],ARRAY['【Related Expression: おまけに; その上; それでいて; それも; それに; (それ)にもかかわらず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"最近のテープレコーダーは小さくて軽く、しかも音が素晴らしくよくなった。","japanese_furigana":"最近のテープレコーダーは小さくて軽く、しかも音が素晴らしくよくなった。","english":"The tape recorders available these days are compact and light, and on top of that, their sound has improved greatly."},{"japanese":"彼は家を買った。しかも大きい庭付きのを（だ）。","japanese_furigana":"彼は家を買った。しかも大きい庭付きのを（だ）。","english":"He bought a house, and more surprisingly, a house with a large yard."}]'::jsonb),
    ('6628d8ac-e009-4f3c-8f03-7a0050e0a396'::uuid,ARRAY['Sentence1 したがって Sentence2']::text[],ARRAY['Use this construction to express A conjunction that is used to indicate that a result/situation follows necessarily from the foregoing situation.. A conjunction that is used to indicate that a result/situation follows necessarily from the foregoing situation.']::text[],ARRAY['【Related Expression: だから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"予算が不足している。したがってこの計画は実行できない。","japanese_furigana":"予算が不足している。したがってこの計画は実行できない。","english":"The budget is insufficient. Therefore this plan cannot be implemented."},{"japanese":"今週は重役達は朝から晩まで会議で忙しい。したがって好きなゴルフをする暇もない。","japanese_furigana":"今週は重役達は朝から晩まで会議で忙しい。したがって好きなゴルフをする暇もない。","english":"This week the executives are busy attending meetings from morning till night. Therefore they don''t even have time to play their favourite golf."}]'::jsonb),
    ('fe574310-d168-4488-b8ae-1ff91974fbaf'::uuid,ARRAY['Canonical pattern: すぐ']::text[],ARRAY['Use this construction to express Without having much temporal or physical distance.. Without having much temporal or physical distance.']::text[],ARRAY['【Related Expression: もうすぐ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"家に帰ったらすぐ、寝てしまいました。","japanese_furigana":"家に帰ったらすぐ、寝てしまいました。","english":"I went to sleep as soon as I got home."},{"japanese":"銀行は駅のすぐ前です。","japanese_furigana":"銀行は駅のすぐ前です。","english":"The bank is right in front of the station."}]'::jsonb),
    ('df9bbcf1-d52e-49fa-83e7-26d2cb900f13'::uuid,ARRAY['Canonical pattern: する（値段・時間）']::text[],ARRAY['Use this construction to express A verb that indicates how much something costs or a duration of time.. A verb that indicates how much something costs or a duration of time.']::text[],ARRAY['The core sense is A verb that indicates how much something costs or a duration of time.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この時計は十万円する・します。","japanese_furigana":"この時計は十万円する・します。","english":"This watch costs 100,000 yen."},{"japanese":"後一年したら大学を出る・出ます。","japanese_furigana":"後一年したら大学を出る・出ます。","english":"In another year I''ll graduate from college."}]'::jsonb),
    ('8bf7e402-a60f-4799-8603-a05a36b6d1b3'::uuid,ARRAY['Canonical pattern: する（属性）']::text[],ARRAY['Use this construction to express Someone or something has some (semi)permanent attribute.. Someone or something has some (semi)permanent attribute.']::text[],ARRAY['【Related Expression: は~が】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"洋子は長い足をしている・います。","japanese_furigana":"洋子は長い足をしている・います。","english":"Yoko has long legs."},{"japanese":"一男は丈夫な体をしています。","japanese_furigana":"一男は丈夫な体をしています。","english":"Kazuo has a strong body."}]'::jsonb),
    ('8beef70a-155c-4c87-b54f-2ff1fa152626'::uuid,ARRAY['Canonical pattern: すると']::text[],ARRAY['Use this construction to express A coordinate conjunction which connects two sentences (the second sentence either describes an event which takes place right after the event described in the first sentence or it expresses a logical guess related to the event in the first sentence.). A coordinate conjunction which connects two sentences (the second sentence either describes an event which takes place right after the event described in the first sentence or it expresses a logical guess related to the event in the first sentence.)']::text[],ARRAY['The core sense is A coordinate conjunction which connects two sentences (the second sentence either describes an event which takes place right after the event described in the first sentence or it expresses a logical guess related to the event in the first sentence.); the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ジョギングを始めました。するとご飯が美味しくなりました。","japanese_furigana":"ジョギングを始めました。するとご飯が美味しくなりました。","english":"I began jogging. Then, I began to have a good appetite."},{"japanese":"A:今日は月曜日ですよ。 B:するとあのデパートは休みですね。","japanese_furigana":"A:今日は月曜日ですよ。 B:するとあのデパートは休みですね。","english":"A: Today is Monday, you know. B: Then, that department store is closed, isn''t it?"}]'::jsonb),
    ('04aec0b7-b2b9-4311-b595-1369a42459ea'::uuid,ARRAY['(i) Nounの せい (で/か/etc.)']::text[],ARRAY['Use this construction to express A dependent noun expressing a cause which brings about an undesirable result.. A dependent noun expressing a cause which brings about an undesirable result.']::text[],ARRAY['【Related Expression: おかげ; 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年は不況のせいで車があまり売れない。","japanese_furigana":"今年は不況のせいで車があまり売れない。","english":"Because of the depression, cars are not selling well this year."},{"japanese":"寝不足のせいか体に力が入らない。","japanese_furigana":"寝不足のせいか体に力が入らない。","english":"Because of lack of sleep, I suppose, I feel weak (literally: the body has no power)."}]'::jsonb),
    ('af30093f-261b-4683-a21c-7ee5ee1d4b64'::uuid,ARRAY['Canonical pattern: せっかく']::text[],ARRAY['Use this construction to express Some situation which seldom occurs has now occurred and one can either make use of it or, to one’s regret, cannot make use of it.. Some situation which seldom occurs has now occurred and one can either make use of it or, to one’s regret, cannot make use of it.']::text[],ARRAY['【Related Expression: わざわざ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"せっかく会いに行ったのに友達はいなかった・いませんでした。","japanese_furigana":"せっかく会いに行ったのに友達はいなかった・いませんでした。","english":"I took the trouble to go see my friend, but he wasn''t at home."},{"japanese":"せっかくいい大学に入ったのだからよく勉強するつもりだ・です。","japanese_furigana":"せっかくいい大学に入ったのだからよく勉強するつもりだ・です。","english":"I entered a good college with great effort, so I intend to study hard."}]'::jsonb),
    ('cb68722f-afea-4e62-b55f-d1c32d967843'::uuid,ARRAY['(i) せめて Number+Counter (ぐらい)~']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker/writer''s minimally satisfactory level.. An adverb that indicates the speaker/writer''s minimally satisfactory level.']::text[],ARRAY['【Related Expression: 少なくとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"百点とは言いませんが、せめて八十点ぐらいは取りたいです。","japanese_furigana":"百点とは言いませんが、せめて八十点ぐらいは取りたいです。","english":"I am not saying that I want to get 100 points, but I would like to get at least 80 points."},{"japanese":"せめて鍋（だけ）でもあれば、ご飯が炊けるんですが。","japanese_furigana":"せめて鍋（だけ）でもあれば、ご飯が炊けるんですが。","english":"If we had a pan, at least, we would be able to cook rice."}]'::jsonb),
    ('5c82ceea-d2df-4b4d-87c3-4732b2b6cbfd'::uuid,ARRAY['(i) Sentence1、 そこで Sentence2']::text[],ARRAY['Use this construction to express A conjunction which connects an event and an action taken at the time of the event. A conjunction which connects an event and an action taken at the time of the event']::text[],ARRAY['The core sense is A conjunction which connects an event and an action taken at the time of the event; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私が手を振ったら、そこで拍手をして下さい。","japanese_furigana":"私が手を振ったら、そこで拍手をして下さい。","english":"When I wave my hand, (literally: then,) please clap your hands."},{"japanese":"彼は飲み物を勧めるかもしれません。そこで、遠慮をしてはいけません。","japanese_furigana":"彼は飲み物を勧めるかもしれません。そこで、遠慮をしてはいけません。","english":"He might offer you a drink. At that time you mustn''t hesitate."}]'::jsonb),
    ('3b922a0d-2940-4cd8-8885-14f1f3be057f'::uuid,ARRAY['Sentence1 そこで 、Sentence2']::text[],ARRAY['Use this construction to express A conjunction which connects a situation presented as a reason and an action taken because of that situation. A conjunction which connects a situation presented as a reason and an action taken because of that situation']::text[],ARRAY['【Related Expression: それで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"友達が夕食は簡単なものでいいと言った。そこで、ピザを注文した。","japanese_furigana":"友達が夕食は簡単なものでいいと言った。そこで、ピザを注文した。","english":"My friend told me that something simple would be fine for supper. So, I ordered a pizza."},{"japanese":"荷物が沢山あるのに雨が降り出した。そこで、タクシーで行くことにした。","japanese_furigana":"荷物が沢山あるのに雨が降り出した。そこで、タクシーで行くことにした。","english":"I had a lot of baggage and it began to rain. Therefore, I decided to go by taxi."}]'::jsonb),
    ('c6af0bb4-204c-400e-9c39-28203661e4a7'::uuid,ARRAY['Canonical pattern: そこを']::text[],ARRAY['Use this construction to express A conjunction used to indicate that in spite of the negative situation mentioned in the previous part of the sentence/discourse some positive effort is made.. A conjunction used to indicate that in spite of the negative situation mentioned in the previous part of the sentence/discourse some positive effort is made.']::text[],ARRAY['The core sense is A conjunction used to indicate that in spite of the negative situation mentioned in the previous part of the sentence/discourse some positive effort is made.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"トムはフットボールの選手としては小さいが、そこを脚力で補っている。","japanese_furigana":"トムはフットボールの選手としては小さいが、そこを脚力で補っている。","english":"Tom is small for a football player, but he makes up for it with his swift legs."},{"japanese":"Ａ：これ以上金を貸すわけにはいかないよ。Ｂ：そこを何とかして下さいませんか。","japanese_furigana":"Ａ：これ以上金を貸すわけにはいかないよ。Ｂ：そこを何とかして下さいませんか。","english":"A: I cannot loan you more money than this. B: But, could you do something about it?"}]'::jsonb),
    ('6bac3843-05d1-4453-b5fd-8f70bd0ae4ec'::uuid,ARRAY['Canonical pattern: そして']::text[],ARRAY['Use this construction to express A coordinate conjunction that connects two sentences.. A coordinate conjunction that connects two sentences.']::text[],ARRAY['【Related Expression: それから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今日は東京に行った・行きました。そして友達に会った・会いました。","japanese_furigana":"今日は東京に行った・行きました。そして友達に会った・会いました。","english":"I went to Tokyo today. And I met my friend there."},{"japanese":"昨日は朝ゴルフをしました。そして午後はテニスをしました。","japanese_furigana":"昨日は朝ゴルフをしました。そして午後はテニスをしました。","english":"Yesterday I played golf in the morning. And I played tennis in the afternoon."}]'::jsonb),
    ('243cb121-c70c-4b36-97bd-9c9fc7e4dfa7'::uuid,ARRAY['(i) {V/Adjective/Noun+Copula}て その上']::text[],ARRAY['Use this construction to express A conjunction which introduces an additional, emphatic statement.. A conjunction which introduces an additional, emphatic statement.']::text[],ARRAY['【Related Expression: おまけに; しかも; それに; うえ(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は一緒にアパートを探してくれて、その上、引っ越しまで手伝ってくれた。","japanese_furigana":"彼は一緒にアパートを探してくれて、その上、引っ越しまで手伝ってくれた。","english":"He looked for an apartment with me, and moreover, he even helped me move."},{"japanese":"この仕事は給料がいいし、その上、時々外国に行く機会もある。","japanese_furigana":"この仕事は給料がいいし、その上、時々外国に行く機会もある。","english":"This job pays a good salary, and what''s more, it offers opportunities to go abroad from time to time."}]'::jsonb),
    ('bd31135c-f5df-4c84-a7f4-f92fa7ac992a'::uuid,ARRAY['(i) そもそも Sentence。']::text[],ARRAY['Use this construction to express A sentence-modifying adverb used when the speaker/writer comments on or questions a fundamental point.. A sentence-modifying adverb used when the speaker/writer comments on or questions a fundamental point.']::text[],ARRAY['【Related Expression: 第一; もともとの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はそもそも、作品のいいところをコメントしないで欠点ばかり指摘する審査のやり方に賛成できない。","japanese_furigana":"私はそもそも、作品のいいところをコメントしないで欠点ばかり指摘する審査のやり方に賛成できない。","english":"To begin with, I cannot agree with our way of judging where we point out only the ﬂaws of a piece and never mention the good points."},{"japanese":"そもそもこんなところにスーパーを造ったことが問題だ。","japanese_furigana":"そもそもこんなところにスーパーを造ったことが問題だ。","english":"The problem is that they built a supermarket in a place like this to begin with."}]'::jsonb),
    ('1fd52370-ce91-4c3c-88d5-10f3d9d3fd18'::uuid,ARRAY['Canonical pattern: それが']::text[],ARRAY['Use this construction to express An interjection which signals that the speaker is going to provide an unexpected response to a question.. An interjection which signals that the speaker is going to provide an unexpected response to a question.']::text[],ARRAY['【Related Expression: それは; ところが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：奨学金がもらえそうですか。Ｂ：（いえ）それが難しそうなんです。","japanese_furigana":"Ａ：奨学金がもらえそうですか。Ｂ：（いえ）それが難しそうなんです。","english":"A: Does it look like you can get a scholarship? B: Well, (no,) it looks difficult."},{"japanese":"A: 試験、どうだった？B:それが、駄目だったんだ。","japanese_furigana":"A: 試験、どうだった？B:それが、駄目だったんだ。","english":"A: How was the exam? B: Well, (I''m sorry to say this, but) it was no good."}]'::jsonb),
    ('168dd4fc-1a3e-4c8c-aed7-730a4e21f21c'::uuid,ARRAY['(i) {Vて/Vます} それから']::text[],ARRAY['Use this construction to express A conjunction that indicates (1) temporally contiguous actions or states, or (2) a cumulative listing of objects, actions or states.. A conjunction that indicates (1) temporally contiguous actions or states, or (2) a cumulative listing of objects, actions or states.']::text[],ARRAY['【Related Expression: から2; し; そして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"昨日は二時間ぐらい友達と飲んでそれからうちに帰った・帰りました。","japanese_furigana":"昨日は二時間ぐらい友達と飲んでそれからうちに帰った・帰りました。","english":"Yesterday I drank with my friend for about two hours and then went home."},{"japanese":"昨日は二時間ぐらい友達と飲んだ。それから本屋に寄ってうちに帰った。","japanese_furigana":"昨日は二時間ぐらい友達と飲んだ。それから本屋に寄ってうちに帰った。","english":"Yesterday I drank with my friend for about two hours. Then I dropped by a bookstore and went home."}]'::jsonb),
    ('463e6a80-36fe-4543-815c-ba60b2baa23d'::uuid,ARRAY['Canonical pattern: それぞれ']::text[],ARRAY['Use this construction to express Each of two or more things/persons.. Each of two or more things/persons.']::text[],ARRAY['【Related Expression: めいめい; おのおの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さんと鈴木さんは、果物とお菓子をそれぞれ買った。","japanese_furigana":"山田さんと鈴木さんは、果物とお菓子をそれぞれ買った。","english":"Yamada and Suzuki bought fruits and cakes, respectively."},{"japanese":"読んだ小説はそれぞれ面白かった。","japanese_furigana":"読んだ小説はそれぞれ面白かった。","english":"Each of the novels I read was interesting (in its own way)."}]'::jsonb),
    ('371d119b-d7f5-4436-9d03-233df39f2a0e'::uuid,ARRAY['Canonical pattern: それだけ']::text[],ARRAY['Use this construction to express An adverbial phrase indicating that the degree of something is proportionate to the degree of the state, action or event mentioned in the preceding sentence.. An adverbial phrase indicating that the degree of something is proportionate to the degree of the state, action or event mentioned in the preceding sentence.']::text[],ARRAY['The core sense is An adverbial phrase indicating that the degree of something is proportionate to the degree of the state, action or event mentioned in the preceding sentence.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"株式投資は当たった時の利益は大きいが、それだけリスクも大きい。","japanese_furigana":"株式投資は当たった時の利益は大きいが、それだけリスクも大きい。","english":"You can make a big proﬁt when you invest in the right stocks, but the risk (of loss) is just as big."},{"japanese":"この仕事は苦労も多いが、それだけやりがいもある。","japanese_furigana":"この仕事は苦労も多いが、それだけやりがいもある。","english":"This job is hard work, but to the same extent I also ﬁnd it rewarding."}]'::jsonb),
    ('e529b7ac-5366-4f64-bb18-36de574b64b7'::uuid,ARRAY['Canonical pattern: それで']::text[],ARRAY['Use this construction to express A conjunction to indicate that what is stated in the preceding sentence is the reason or cause for what is stated in the following sentence.. A conjunction to indicate that what is stated in the preceding sentence is the reason or cause for what is stated in the following sentence.']::text[],ARRAY['【Related Expression: だから; ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"昨日は風邪を引きました。それで学校を休んだんです。","japanese_furigana":"昨日は風邪を引きました。それで学校を休んだんです。","english":"I had a cold yesterday. That''s why I took a day off from school."},{"japanese":"ちょっと大阪で用事がありました。それで昨日いなかったんです。","japanese_furigana":"ちょっと大阪で用事がありました。それで昨日いなかったんです。","english":"I had some business in Osaka. That''s why I wasn''t here yesterday."}]'::jsonb),
    ('3c470a31-b9c0-42e8-bbfe-644560dbc44b'::uuid,ARRAY['Canonical pattern: それでは']::text[],ARRAY['Use this construction to express If that is the case. If that is the case']::text[],ARRAY['【Related Expression: それなら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:このオレンジは甘くないです。 B:それではこれはどう（ですか）。","japanese_furigana":"A:このオレンジは甘くないです。 B:それではこれはどう（ですか）。","english":"A: This orange is not sweet. B: How about this one, then?"},{"japanese":"A:僕は魚も肉も嫌いです。 B:それでは何を食べるんですか。","japanese_furigana":"A:僕は魚も肉も嫌いです。 B:それでは何を食べるんですか。","english":"A: I hate both fish and meat. B: Then, what do you eat."}]'::jsonb),
    ('320f85a5-95d3-4d5f-9f81-994208a9900c'::uuid,ARRAY['(i) Sentence1(しかし) それでも Sentence2']::text[],ARRAY['Use this construction to express In spite of the circumstance expressed in the preceding sentence.. In spite of the circumstance expressed in the preceding sentence.']::text[],ARRAY['【Related Expression: (それ)にもかかわらず; ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"両親は二人の結婚に反対している。それでも二人は結婚するつもりらしい。","japanese_furigana":"両親は二人の結婚に反対している。それでも二人は結婚するつもりらしい。","english":"The parents are opposed to the couple''s marriage. Nevertheless, they seem intent to marrying."},{"japanese":"暑いので扇風機をつけたが、それでもまだ暑かった。","japanese_furigana":"暑いので扇風機をつけたが、それでもまだ暑かった。","english":"It was so hot that we turned on an electric fan, but it was still hot."}]'::jsonb),
    ('e4e29a58-4a68-4c46-ae6f-0ecf992cafce'::uuid,ARRAY['(i) Noun 1 {と/に/、}Noun 2 {と/に/、} … それと 、Noun']::text[],ARRAY['Use this construction to express A conjunction which introduces an additional item or statement.. A conjunction which introduces an additional item or statement.']::text[],ARRAY['【Related Expression: それから; それに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"林檎三つとオレンジ二つ、それと、バナナを三本下さい。","japanese_furigana":"林檎三つとオレンジ二つ、それと、バナナを三本下さい。","english":"Give me three apples and two oranges, and three bananas, as well."},{"japanese":"スポーツはテニスとゴルフをします。それと、学生時代はアイスホッケーをしていました。","japanese_furigana":"スポーツはテニスとゴルフをします。それと、学生時代はアイスホッケーをしていました。","english":"S1: Speaking of sports, I play tennis and golf. S2: In addition, I played ice hockey at school (literally: in my school days)."}]'::jsonb),
    ('1555f248-efb1-43a5-9a24-01f204787322'::uuid,ARRAY['(i) Sentence1 それどころか Sentence2']::text[],ARRAY['Use this construction to express A conjunction that is used to indicate that the level/degree of a fact or a situation expressed in the second sentence is far above or below the level/degree of a fact or a situation expressed in the first sentence.. A conjunction that is used to indicate that the level/degree of a fact or a situation expressed in the second sentence is far above or below the level/degree of a fact or a situation expressed in the first sentence.']::text[],ARRAY['【Related Expression: どころか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミスさんは漢字が書けない。それどころか、平仮名も満足に書けない。","japanese_furigana":"スミスさんは漢字が書けない。それどころか、平仮名も満足に書けない。","english":"Mr. Smith cannot write kanji. As a matter of fact, he cannot write even hiragana satisfactorily."},{"japanese":"Ａ：今晩パーティーに行かない？ Ｂ：それどころ{か、/じゃないよ。}親父が入院したんだ。","japanese_furigana":"Ａ：今晩パーティーに行かない？ Ｂ：それどころ{か、/じゃないよ。}親父が入院したんだ。","english":"A: Shall we go to the party tonight? B: No way (literally: Far from it). Dad got hospitalized."}]'::jsonb),
    ('514ad5f8-a2a2-4ea8-80d0-96157d0a0c78'::uuid,ARRAY['Canonical pattern: それとも']::text[],ARRAY['Use this construction to express A coordinate conjunction which connects two alternatives expressed by sentences.. A coordinate conjunction which connects two alternatives expressed by sentences.']::text[],ARRAY['【Related Expression: か1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この本が間違っているか（それとも）私が間違っているかどちらだ・です。","japanese_furigana":"この本が間違っているか（それとも）私が間違っているかどちらだ・です。","english":"It''s either that this book is wrong or that I am wrong."},{"japanese":"刺身を食べますか。それともすき焼きにしますか。","japanese_furigana":"刺身を食べますか。それともすき焼きにしますか。","english":"Will you have sashimi, or will you have sukiyaki?"}]'::jsonb),
    ('6da81e34-72a2-46c2-8c83-e121e1e90470'::uuid,ARRAY['Canonical pattern: それなら']::text[],ARRAY['Use this construction to express If that is the case,. If that is the case,']::text[],ARRAY['【Related Expression: それでは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:頭が痛いんです。 B:それなら直ぐ寝なさい。","japanese_furigana":"A:頭が痛いんです。 B:それなら直ぐ寝なさい。","english":"A: I have a headache. B: In that case, go to sleep right away."},{"japanese":"A:映画を見に行きませんか。 B:明日試験があるんです。 A:それなら、明後日はどうですか。","japanese_furigana":"A:映画を見に行きませんか。 B:明日試験があるんです。 A:それなら、明後日はどうですか。","english":"A: Wouldn''t you like to go see a movie? B: I have an exam tomorrow. A: Then, how about the day after tomorrow?"}]'::jsonb),
    ('1796397b-536b-4f43-8eb9-b672a5af9459'::uuid,ARRAY['(i) Noun 1 {と/に/、}Noun 2 {と/に/、} … それに Noun']::text[],ARRAY['Use this construction to express A conjunction which introduces an additional item or statement.. A conjunction which introduces an additional item or statement.']::text[],ARRAY['【Related Expression: おまけに; しかも; その上; それと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ここのモーニングセットはコーヒーにトースト、それにゆで卵が付いている。","japanese_furigana":"ここのモーニングセットはコーヒーにトースト、それにゆで卵が付いている。","english":"The \"morning set\" here includes coffee and some toast; in addition, there is a boiled egg (literally: it is accompanied by a boiled egg)."},{"japanese":"車を買っても置く所がないし、それにあまり乗る機会もない。","japanese_furigana":"車を買っても置く所がないし、それにあまり乗る機会もない。","english":"Even if we bought a car, there would be no place to park it, and moreover, there would be few occasions to use it"}]'::jsonb),
    ('656e2e98-9aa9-477e-bb50-9835978c2d55'::uuid,ARRAY['Canonical pattern: それは']::text[],ARRAY['Use this construction to express An interjection which is used when the speaker emphatically provides an expected response to a question.. An interjection which is used when the speaker emphatically provides an expected response to a question.']::text[],ARRAY['【Related Expression: それが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：勝ちたいでしょうね。Ｂ：（ええ）それは勝ちたいですよ。","japanese_furigana":"Ａ：勝ちたいでしょうね。Ｂ：（ええ）それは勝ちたいですよ。","english":"A: I bet you want to win (the game). B: (Yes,) of course, I do."},{"japanese":"A: 国へ帰りたいと思うことがありますか。B: （ええ、）それはありますよ。","japanese_furigana":"A: 国へ帰りたいと思うことがありますか。B: （ええ、）それはありますよ。","english":"A: Are there times when you want to go back to your country? B: (Yes,) Of course."}]'::jsonb),
    ('b43f62c1-6f64-4a43-877c-c4e7c298125c'::uuid,ARRAY['(i) AdverbPhrase1 それも AdverbPhrase2(Verbal)']::text[],ARRAY['Use this construction to express A conjunction which is used to add more specific information to information about a rather uncommon action or state.. A conjunction which is used to add more specific information to information about a rather uncommon action or state.']::text[],ARRAY['【Related Expression: しかも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"英語で、それも早口で話されたので全然分からなかった。","japanese_furigana":"英語で、それも早口で話されたので全然分からなかった。","english":"Because he spoke (literally: I was talked to) in English, and what''s worse, rapidly, I didn''t understand anything."},{"japanese":"彼女は銀座の、それも一流の店でばかり買い物をする。","japanese_furigana":"彼女は銀座の、それも一流の店でばかり買い物をする。","english":"She always does her shopping at shops in Ginza, and moreover, at first-class ones."}]'::jsonb),
    ('065709ae-3d13-4666-bca9-8baaeb788fcd'::uuid,ARRAY['S1 informal だが 、 S2 informal']::text[],ARRAY['Use this construction to express A conjunction that expresses something that is contrasted with what is expressed in the previous sentence.. A conjunction that expresses something that is contrasted with what is expressed in the previous sentence.']::text[],ARRAY['【Related Expression: だけど; でも; が; けれど(も); のに; しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の経済力は伸びている。だが、いつまで続くかは分からない。","japanese_furigana":"日本の経済力は伸びている。だが、いつまで続くかは分からない。","english":"Japanese economic power is growing, but we can''t tell how long it will last."},{"japanese":"都会の生活は便利だ。だが、ストレスが多すぎる。","japanese_furigana":"都会の生活は便利だ。だが、ストレスが多すぎる。","english":"Urban life is convenient. But there are too many stresses."}]'::jsonb),
    ('0c262a40-2cc6-4bb2-9929-933cb953ec10'::uuid,ARRAY['(i) たかが Nounだ']::text[],ARRAY['Use this construction to express A noun modiﬁer used when the speaker thinks little of the referent of the modiﬁed noun or noun phrase.. A noun modiﬁer used when the speaker thinks little of the referent of the modiﬁed noun or noun phrase.']::text[],ARRAY['【Related Expression: ただの; たった】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"たかが子供の言ったことだ。そんなに深刻に考えることはない。","japanese_furigana":"たかが子供の言ったことだ。そんなに深刻に考えることはない。","english":"It''s just something a child told you. You don''t have to take it so seriously."},{"japanese":"たかが漫画(くらい)と馬鹿にしてはいけない。","japanese_furigana":"たかが漫画(くらい)と馬鹿にしてはいけない。","english":"You shouldn''t make light of it saying it''s just a cartoon."}]'::jsonb),
    ('92ce285f-a2f2-410c-b500-4c262bc0766b'::uuid,ARRAY['S1 (S2…) だからと言って Sn Where Sn often ends with わけではない or とは限らない']::text[],ARRAY['Use this construction to express A coordinate conjunction indicating that even if one accepts a premise expressed in the preceding sentence(s) one cannot jump to an expected conclusion from the premise.. A coordinate conjunction indicating that even if one accepts a premise expressed in the preceding sentence(s) one cannot jump to an expected conclusion from the premise.']::text[],ARRAY['【Related Expression: からと言って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"チェンさんは日本語が苦手だ。テストではいつも半分も出来ない。だからと言って、頭が悪いわけではない。","japanese_furigana":"チェンさんは日本語が苦手だ。テストではいつも半分も出来ない。だからと言って、頭が悪いわけではない。","english":"Mr. Cheng is not good at Japanese. On a test he cannot even finish half of it. But it doesn''t follow from this that he is not smart."},{"japanese":"吉田さんは日本人だ。しかも、小説家だ。だからと言って、日本語が教えられるとは限らない。","japanese_furigana":"吉田さんは日本人だ。しかも、小説家だ。だからと言って、日本語が教えられるとは限らない。","english":"Ms. Yoshida is Japanese. And she is a novelist. But she may not be able to teach Japanese."}]'::jsonb),
    ('c8a2695a-1c5c-4b32-a505-438ae5aab759'::uuid,ARRAY['(i) {V/Adjective い} informal だけで(は)なく Not only ~']::text[],ARRAY['Use this construction to express Not only X but also Y, where X and Y can be either a noun, a verb, or an adjective.. Not only X but also Y, where X and Y can be either a noun, a verb, or an adjective.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~も】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの人はよく勉強するだけで(は)なくよく遊ぶ・遊びます。","japanese_furigana":"あの人はよく勉強するだけで(は)なくよく遊ぶ・遊びます。","english":"He not only studies hard, but also plays a lot."},{"japanese":"あの人は頭がいいだけで(は)なくよく勉強(も)する・します。","japanese_furigana":"あの人は頭がいいだけで(は)なくよく勉強(も)する・します。","english":"He is not only smart; he studies hard, too."}]'::jsonb),
    ('81c1e397-ef58-46f3-ab52-c8dbff464629'::uuid,ARRAY['(i) Sentence1。 ただ 、Sentence2。']::text[],ARRAY['Use this construction to express A conjunction that introduces a supplementary remark.. A conjunction that introduces a supplementary remark.']::text[],ARRAY['【Related Expression: なお; もっとも; ただし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この辺りは駅にもスーパーにも近くて便利だ。ただ環境があまりよくない。","japanese_furigana":"この辺りは駅にもスーパーにも近くて便利だ。ただ環境があまりよくない。","english":"This area is close to both the station and a supermarket, so it''s convenient, but the environment is not very good."},{"japanese":"とてもいいコンピュータだと思います。ただ値段が問題ですね。","japanese_furigana":"とてもいいコンピュータだと思います。ただ値段が問題ですね。","english":"I think this is a very good computer. But, the price is a problem."}]'::jsonb),
    ('fee7902b-56eb-4674-bb15-cac228badf47'::uuid,ARRAY['(i) ただ One+Counter (のNoun)']::text[],ARRAY['Use this construction to express An adverb which emphasizes the idea of "only".. An adverb which emphasizes the idea of "only".']::text[],ARRAY['【Related Expression: たった】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼のただ一つの欠点は時間にルーズだということだ。","japanese_furigana":"彼のただ一つの欠点は時間にルーズだということだ。","english":"His only (one) defect is that he is not punctual (literally: he is slack about time)."},{"japanese":"彼女はただの一度も手紙をくれなかった。","japanese_furigana":"彼女はただの一度も手紙をくれなかった。","english":"She didn''t write me even once (literally: only once)."}]'::jsonb),
    ('2a6ef06d-e29c-451b-838e-5549ee6a603f'::uuid,ARRAY['ただの Noun']::text[],ARRAY['Use this construction to express Not deserving to be mentioned.. Not deserving to be mentioned.']::text[],ARRAY['【Related Expression: 普通の; に過ぎない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はただの平社員ですから、そんなことは知りません。","japanese_furigana":"私はただの平社員ですから、そんなことは知りません。","english":"I''m only an ordinary employee, so I''m not aware of that."},{"japanese":"ただの風邪だと思っていたら、肺炎だった。","japanese_furigana":"ただの風邪だと思っていたら、肺炎だった。","english":"I thought it was an ordinary cold, but it was pneumonia."}]'::jsonb),
    ('3961d701-97d7-473f-8ed0-d0b8118b9eaf'::uuid,ARRAY['(i) Vinformal past って']::text[],ARRAY['Use this construction to express Even if someone did something or something were in some state (the desired result would not come about) or even if someone or something is in some state.. Even if someone did something or something were in some state (the desired result would not come about) or even if someone or something is in some state.']::text[],ARRAY['【Related Expression: ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの人には話したって分からない・分かりません。","japanese_furigana":"あの人には話したって分からない・分かりません。","english":"Even if I tell him that, he won''t understand it."},{"japanese":"僕はその切符を高くたって買う・買います。","japanese_furigana":"僕はその切符を高くたって買う・買います。","english":"I will buy the ticket even if it is expensive."}]'::jsonb),
    ('f14e80b5-7007-40fa-935a-33c1a2b761c9'::uuid,ARRAY['Vinformal past ところで']::text[],ARRAY['Use this construction to express Even if an action or a state were realised.. Even if an action or a state were realised.']::text[],ARRAY['【Related Expression: ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"どんなに低く見積もったところで、工費は五億円を超えるだろう。","japanese_furigana":"どんなに低く見積もったところで、工費は五億円を超えるだろう。","english":"No matter how low we estimate the construction expense it will go beyond 500 million yen."},{"japanese":"この薬を飲んだところで、風邪がすぐ治るわけじゃない。","japanese_furigana":"この薬を飲んだところで、風邪がすぐ治るわけじゃない。","english":"Even if you took this medicine, it would not be the case that your cold would be cured right away."}]'::jsonb),
    ('92e933a6-f472-4318-aa0c-96a140567cf1'::uuid,ARRAY['(i) Vinformal past なり ( で )']::text[],ARRAY['Use this construction to express A conjunction indicating that a situation or condition remains unaltered.. A conjunction indicating that a situation or condition remains unaltered.']::text[],ARRAY['【Related Expression: まま(で)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は椅子に腰掛けたなり(で)、ずっと黙っていた。","japanese_furigana":"彼は椅子に腰掛けたなり(で)、ずっと黙っていた。","english":"He sat in the chair and stayed there, silent the whole time."},{"japanese":"片足を上げたなりの格好で、数秒間目をつぶるように言われた。","japanese_furigana":"片足を上げたなりの格好で、数秒間目をつぶるように言われた。","english":"I was told to close my eyes for a few seconds while I kept lifting one foot off the ground."}]'::jsonb),
    ('a32ab815-303d-4def-98ac-42df0358d3d5'::uuid,ARRAY['(i) Noun 1 だの Noun 2 だの (Noun 3 だの )']::text[],ARRAY['Use this construction to express A conjunction that lists nouns/quotes inexhaustively.. A conjunction that lists nouns/quotes inexhaustively.']::text[],ARRAY['【Related Expression: とか; や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"庭にはすみれだのチューリップだのつつじだの、花がたくさん咲いていた。","japanese_furigana":"庭にはすみれだのチューリップだのつつじだの、花がたくさん咲いていた。","english":"In the garden, many ﬂowers such as pansies, tulips, azaleas and others, were in bloom."},{"japanese":"学生たちは食堂のご飯がまずいだの、授業がつまらないだのと、いつも不平を言っている。","japanese_furigana":"学生たちは食堂のご飯がまずいだの、授業がつまらないだのと、いつも不平を言っている。","english":"The students are always complaining that the food at the cafeteria isn''t good, or their classes are boring and so on."}]'::jsonb),
    ('fa211218-7fc7-4c62-8b4a-3eed0d0ea61b'::uuid,ARRAY['(i) Vinformal nonpast たびに']::text[],ARRAY['Use this construction to express A conjunction to express that each time someone/something does something, something else takes place.. A conjunction to express that each time someone/something does something, something else takes place.']::text[],ARRAY['【Related Expression: いつ(で)も; といつ(で)も; 時(に)は】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本へ行くたびに新しいことを学んで帰ります。","japanese_furigana":"日本へ行くたびに新しいことを学んで帰ります。","english":"Each time I go to Japan I come home having learned something new."},{"japanese":"父は旅行のたびにお土産を買ってきてくれる。","japanese_furigana":"父は旅行のたびにお土産を買ってきてくれる。","english":"On every trip my father comes back with souvenirs."}]'::jsonb),
    ('10c71762-7c2d-4236-aebf-838caa023492'::uuid,ARRAY['Sentence1。 (Sentence2。…。) ちなみに Sentence(n)。']::text[],ARRAY['Use this construction to express A conjunction to indicate that what follows is additional information related to the previously stated main theme. A conjunction to indicate that what follows is additional information related to the previously stated main theme']::text[],ARRAY['The core sense is A conjunction to indicate that what follows is additional information related to the previously stated main theme; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼の小説はポストモダン的で大変気に入ってる。解釈が読み手にゆだねられているところがよい。ちなみに、去年の作品はベストセラー第一位だった。","japanese_furigana":"彼の小説はポストモダン的で大変気に入ってる。解釈が読み手にゆだねられているところがよい。ちなみに、去年の作品はベストセラー第一位だった。","english":"I love his postmodern novels. I like the way he leaves the interpretation to the reader. Incidentally, his work published last year topped the bestseller list."},{"japanese":"先週から上野の美術館で印象派の絵画展が開かれており、ルノアール、モネ、マネなどの代表作が出品されている。ちなみに、入場料は大人三千五百円、子供千円である。","japanese_furigana":"先週から上野の美術館で印象派の絵画展が開かれており、ルノアール、モネ、マネなどの代表作が出品されている。ちなみに、入場料は大人三千五百円、子供千円である。","english":"An exhibit of Impressionists'' paintings opened last week at an art museum in Ueno and representative works of Renoir, Monet and Manet, among others, are displayed there. Incidentally, the admission fee is 3,500 yen for adults and 1,000 yen for children."}]'::jsonb),
    ('946fe138-92fa-48a5-a246-c6c1863ebc6f'::uuid,ARRAY['(i) つい Verb']::text[],ARRAY['Use this construction to express An adverb used to describe someone doing something without being able to control himself/herself or used to indicate the closeness of a time or a place.. An adverb used to describe someone doing something without being able to control himself/herself or used to indicate the closeness of a time or a place.']::text[],ARRAY['【Related Expression: うっかり; 思わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"楽しかったので、つい飲みすぎてしまった。","japanese_furigana":"楽しかったので、つい飲みすぎてしまった。","english":"Because I had such a good time, I ended up drinking too much (without meaning to)."},{"japanese":"ついさっきまで山口さんが来ていたんです。","japanese_furigana":"ついさっきまで山口さんが来ていたんです。","english":"Mr. Yamaguchi was here until just a little while ago."}]'::jsonb),
    ('24364042-4e7c-4eac-a4b3-1bd8632774b3'::uuid,ARRAY['Canonical pattern: ついては']::text[],ARRAY['Use this construction to express A sentence-initial conjunction that means “with regard to this,” referring to what is stated in the preceding sentence.. A sentence-initial conjunction that means “with regard to this,” referring to what is stated in the preceding sentence.']::text[],ARRAY['【Related Expression: について(は); その為; それ故】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"コンピュータウイルスが全国的に広がっています。ついては、不審なメールが届いた場合は、添付ファイルを開くことなく当該メールを削除して下さい。","japanese_furigana":"コンピュータウイルスが全国的に広がっています。ついては、不審なメールが届いた場合は、添付ファイルを開くことなく当該メールを削除して下さい。","english":"Computer viruses are spreading across the country. Because of this, if you receive a suspicious e-mail (literally: in the event a suspicious e-mail arrives), delete the email without opening the attached ﬁle."},{"japanese":"この書類は契約文の日本語抄訳です。ついては、本訳をご参照の上、ウェブの英文契約書にご同意いただく必要があります。","japanese_furigana":"この書類は契約文の日本語抄訳です。ついては、本訳をご参照の上、ウェブの英文契約書にご同意いただく必要があります。","english":"This document is the abridged Japanese translation of the agreement. Therefore, it is necessary for you to refer to this translation and accept the English agreement posted online."}]'::jsonb),
    ('cd8dd9ea-ac31-438d-9129-d40b7b999507'::uuid,ARRAY['(i) {V/Adjective い}informal nonpast んだ っけ']::text[],ARRAY['Use this construction to express A colloquial sentence final particle marking a question.. A colloquial sentence final particle marking a question.']::text[],ARRAY['【Related Expression: か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"鈴木さんは英語が話せるんだっけ。","japanese_furigana":"鈴木さんは英語が話せるんだっけ。","english":"Can you speak English, Mr. Suzuki? / Can Mr. Suzuki speak English?"},{"japanese":"鈴木さんは英語が話せた（んだ）っけ。","japanese_furigana":"鈴木さんは英語が話せた（んだ）っけ。","english":"Can you speak English, Mr. Suzuki? / Can Mr. Suzuki speak English?"}]'::jsonb),
    ('62cf05c2-c302-4654-9337-b30b71ae6894'::uuid,ARRAY['Vます つつ']::text[],ARRAY['Use this construction to express (1) an auxiliary which expresses an action in progress; (2) a conjunction which is used to present two concurrent actions.. (1) an auxiliary which expresses an action in progress; (2) a conjunction which is used to present two concurrent actions.']::text[],ARRAY['【Related Expression: いる; ながら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"台風が九州に接近しつつある。","japanese_furigana":"台風が九州に接近しつつある。","english":"A typhoon is approaching Kyushu."},{"japanese":"彼女は夫の無罪を信じつつ息を引き取った。","japanese_furigana":"彼女は夫の無罪を信じつつ息を引き取った。","english":"She died believing that her husband was innocent."}]'::jsonb),
    ('7c523dc5-ce95-4d75-943c-912799a8ae8a'::uuid,ARRAY['(i) Sentence 1 (Sentence2…) つまり Sentence Noun']::text[],ARRAY['Use this construction to express An adverb that is used to summarise or rephrase what has been mentioned/stated in the preceding context.. An adverb that is used to summarise or rephrase what has been mentioned/stated in the preceding context.']::text[],ARRAY['【Related Expression: 結局; すなわち; ようするに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ベルリンの壁が崩れた。これはつまり、民主化の嵐が始まったということだ。","japanese_furigana":"ベルリンの壁が崩れた。これはつまり、民主化の嵐が始まったということだ。","english":"The Berlin Wall fell apart. This means that the storm of democratization has started."},{"japanese":"私の母の弟、つまり、叔父が最近離婚した。","japanese_furigana":"私の母の弟、つまり、叔父が最近離婚した。","english":"My mother''s younger brother, that is to say, my uncle, has recently divorced."}]'::jsonb),
    ('45d57a8a-0062-4238-b8f9-3aba77874c43'::uuid,ARRAY['(i) Noun である']::text[],ARRAY['Use this construction to express A copula which is used in formal writing and formal speech.. A copula which is used in formal writing and formal speech.']::text[],ARRAY['【Related Expression: だ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"「坊っちゃん」は漱石の初期の代表作である。","japanese_furigana":"「坊っちゃん」は漱石の初期の代表作である。","english":"Botchan is representative of Soseki''s early work."},{"japanese":"今年の水不足は極めて深刻である。","japanese_furigana":"今年の水不足は極めて深刻である。","english":"The water shortage this year is extremely serious."}]'::jsonb),
    ('24cec19f-866a-4022-b7b0-7a33810ec5d3'::uuid,ARRAY['(i) Verb ては']::text[],ARRAY['Use this construction to express A conjunction which presents an action/state as a topic about which a negative comment is given.. A conjunction which presents an action/state as a topic about which a negative comment is given.']::text[],ARRAY['The core sense is A conjunction which presents an action/state as a topic about which a negative comment is given.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"そんなに勉強しては、体を壊しますよ。","japanese_furigana":"そんなに勉強しては、体を壊しますよ。","english":"If you study that hard, you will ruin your health."},{"japanese":"こんなに寒くては外出できません。","japanese_furigana":"こんなに寒くては外出できません。","english":"We cannot go out in this cold weather (literally: when it is this cold)."}]'::jsonb),
    ('aee1fda4-340c-40e3-8a00-89296b8a0449'::uuid,ARRAY['(i) Noun でも']::text[],ARRAY['Use this construction to express The て form of です plus も ‘even’.. The て form of です plus も ‘even’.']::text[],ARRAY['The core sense is The て form of です plus も ‘even’.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"先生でも間違う・間違います。","japanese_furigana":"先生でも間違う・間違います。","english":"Even a teacher makes mistakes."},{"japanese":"私は難しい仕事でもする・します。","japanese_furigana":"私は難しい仕事でもする・します。","english":"I will even do a difficult job."}]'::jsonb),
    ('59b0e87b-efee-4f72-bf27-3ba252e06944'::uuid,ARRAY['(i) NP とあっては']::text[],ARRAY['Use this construction to express A conditional phrase that indirectly presents a factual situation as a reason.. A conditional phrase that indirectly presents a factual situation as a reason.']::text[],ARRAY['【Related Expression: (の)であれば; (の)なら; (の)だから; (な)ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"社長の頼みとあっては断るわけにはいかない。","japanese_furigana":"社長の頼みとあっては断るわけにはいかない。","english":"If (it''s true that) it''s a favour for the president, I can''t say no."},{"japanese":"全商品が3割引きで買えるとあっては、遠方からわざわざ人が買いに来るのもうなずける。","japanese_furigana":"全商品が3割引きで買えるとあっては、遠方からわざわざ人が買いに来るのもうなずける。","english":"If (it''s true that) you can buy everything at 30% off, I understand why people come from far away to shop (here)."}]'::jsonb)
